"""Editorial source for the English and Japanese research guide.

[[SOURCE_ID]] is resolved to a numbered, page-local reference by build_site.py.
{{FIGURE_ID}} inserts a credited figure with accessible alternative text.
"""

PAGES = {}

def page(key, ja_title, en_title, ja_lead, en_lead, sections):
    PAGES[key] = dict(title={'ja': ja_title, 'en': en_title},
                      lead={'ja': ja_lead, 'en': en_lead}, sections=sections)

def s(key, ja_title, en_title, ja, en):
    return dict(id=key, title={'ja': ja_title, 'en': en_title}, body={'ja': ja, 'en': en})

page('index', 'マインドアップロードを、実験可能な研究へ。',
     'Make mind uploading an experimental science.',
     '脳を測り、モデルを作り、同じ条件で確かめる。全脳エミュレーションの実現に必要な技術と、次に解くべき問題を一次資料から整理します。',
     'Measure a brain, build a model, and test both under matched conditions. A source-grounded guide to the technologies and experiments needed for whole-brain emulation.', [
 s('starting-point', '何を実現したいのでしょうか', 'What are we trying to build?',
 '''<p><strong>全脳エミュレーション（WBE）</strong>は、特定の脳の構造と状態を測定し、その情報処理を計算機上で再現する研究構想です。一般的な脳のシミュレーションを大きくすることに加え、元の個体との対応を検証する必要があります。どの状態を、どの精度で測れば十分かは未解決です。[[CCFAQ]][[XKB4CG64]]</p>
 <div class="key"><p><strong>現在地：</strong>昆虫の大規模な接続図、哺乳類の局所回路の構造と活動の対応付け、接続図に制約された神経活動予測は実現しています。一方、個人の記憶を保持する人間のWBEは、ここで確認した研究では実証されていません。[[ADD196]][[6TNZ57MZ]][[XMYSQXY8]][[REPORTFINAL]]</p></div>{{pipeline}}''',
 '''<p><strong>Whole-brain emulation (WBE)</strong> aims to reproduce a particular brain's information processing from measurements of its structure and state. In addition to constructing a large brain simulation, the research needs tests of correspondence to the original individual. The sufficient state variables and measurement precision remain open questions.[[CCFAQ]][[XKB4CG64]]</p>
 <div class="key"><p><strong>Current position:</strong> large insect connectomes, paired structure–activity measurements in mammalian tissue, and connectome-constrained activity prediction are established achievements. The research reviewed here does not demonstrate human WBE retaining an individual's memories.[[ADD196]][[6TNZ57MZ]][[XMYSQXY8]][[REPORTFINAL]]</p></div>{{pipeline}}'''),
 s('milestones', '2024–2026年の主要な前進', 'Milestones from 2024–2026',
 '''<div class="cards"><article class="card"><span class="k">2024 · 構造</span><h3>成体ハエの脳をつなぐ</h3><p>FlyWireは雌成体の脳で139,255ニューロンの接続図を報告しました。学習済みの機能を丸ごと再現したという意味ではありません。[[ADD196]]</p></article><article class="card"><span class="k">2025 · 構造＋機能</span><h3>MICrONSで対応を測る</h3><p>マウス視覚野の約75,000ニューロンのカルシウム活動を、20万超の細胞と約5億シナプスを含む電子顕微鏡再構成に対応付けました。対象は脳の一部です。[[6TNZ57MZ]]</p></article><article class="card"><span class="k">2025 · 計測</span><h3>光学顕微鏡で密な回路へ</h3><p>LICONNは組織の拡大と分子標識を組み合わせ、哺乳類脳組織の密な接続再構成を示しました。[[ADD198]]</p></article><article class="card"><span class="k">2026 · 身体との接続</span><h3>脳と腹側神経索を統合</h3><p>BANCとMaleCNSにより、成体ハエの脳だけでなく身体制御につながる中枢神経系を解析する基盤が広がりました。[[ADD199]][[ADD188]]</p></article></div>{{flywire}}''',
 '''<div class="cards"><article class="card"><span class="k">2024 · Structure</span><h3>Wiring an adult fly brain</h3><p>FlyWire reported a connectome of 139,255 neurons in an adult female brain. The map does not itself reproduce the animal's learned function.[[ADD196]]</p></article><article class="card"><span class="k">2025 · Structure + function</span><h3>Measuring correspondence</h3><p>MICrONS paired calcium recordings from around 75,000 mouse visual-cortex neurons with an EM reconstruction containing over 200,000 cells and about half a billion synapses. It covers part of a brain.[[6TNZ57MZ]]</p></article><article class="card"><span class="k">2025 · Measurement</span><h3>Dense circuits with light microscopy</h3><p>LICONN combined expansion and molecular labelling to reconstruct dense connectivity in mammalian brain tissue.[[ADD198]]</p></article><article class="card"><span class="k">2026 · Embodiment</span><h3>Connecting brain and nerve cord</h3><p>BANC and MaleCNS extend analysis to adult fly central nervous systems that include circuits linking the brain to bodily control.[[ADD199]][[ADD188]]</p></article></div>{{flywire}}'''),
 s('carboncopies', 'Carboncopiesが取り組む「測定からモデルへ」', 'Carboncopies: from measurements to models',
 '''<p>Carboncopies Foundationの現在の研究計画では、<strong>Brain Emulation Challenge</strong>、開発基盤の<strong>BrainGenix</strong>、WBEロードマップの更新が重要な柱です。Challengeでは正解が既知の人工神経回路を使い、制限された観測からどこまで機能を復元できるかを調べます。生物学的実証とは区別しながら、方法を比較できる実験環境を作る取り組みです。[[CCRESEARCH]][[CCCHALLENGE]]</p><p><a class="button" href="carboncopies.html">Carboncopiesの研究を詳しく見る →</a></p>''',
 '''<p>Current Carboncopies Foundation work centres on the <strong>Brain Emulation Challenge</strong>, the <strong>BrainGenix</strong> platform, and an updated WBE roadmap. The Challenge uses synthetic circuits with known ground truth to test reconstruction from limited observations. This provides a controlled comparison of methods; biological validation is a separate step.[[CCRESEARCH]][[CCCHALLENGE]]</p><p><a class="button" href="carboncopies.html">Explore Carboncopies research →</a></p>'''),
 s('read', '研究の道筋をたどる', 'Follow the research path',
 '''<p>まず<a href="science.html">科学的基礎</a>で必要な情報を整理し、<a href="progress.html">到達点</a>で論文が示した範囲を確認してください。次に<a href="validation.html">検証</a>で成功条件を定め、<a href="future.html">技術ロードマップ</a>と<a href="action.html">研究の始め方</a>へ進めます。<a href="resources.html">文献ライブラリー</a>では周辺技術も含めて検索できます。</p><p class="small muted">2026年11月4日確認。実証研究・理論モデル・プレプリント・団体の計画を区別して記載しています。収録文献は範囲を定めた探索結果であり、分野全体の完全な網羅を意味しません。</p>''',
 '''<p>Start with <a href="science.html">scientific foundations</a>, check what experiments establish in <a href="progress.html">current evidence</a>, and define success using <a href="validation.html">validation</a>. Continue to the <a href="future.html">technical roadmap</a> and <a href="action.html">research projects</a>. The searchable <a href="resources.html">literature library</a> includes enabling technologies.</p><p class="small muted">Checked 4 November 2026. Experiments, theoretical models, preprints, and organizational plans are labelled separately. This is a scoped literature search, not a claim of exhaustive coverage of the field.</p>''')])

page('science', '脳を再現するには、何を測る必要がありますか',
     'What must we measure to reproduce a brain?',
     '接続、細胞の応答、可塑性、分子状態、身体との相互作用。それぞれの情報が何を制約するのかを整理します。',
     'Connectivity, cellular responses, plasticity, molecular state, and interaction with a body constrain different aspects of a model.', [
 s('state', '構造・状態・更新規則を分ける', 'Separate structure, state, and update rules',
 '''<p>モデルは概念的に <code>x(t+Δt)=F(x(t),u(t);θ)</code> と書けます。<code>x</code>は膜電位や適応状態、<code>u</code>は感覚入力、<code>θ</code>は接続や伝達特性などのパラメーターです。長期学習では<code>θ</code>自体も変化します。「どこがつながるか」と「その接続がどう働くか」を分けることで、測定の不足を具体化できます。[[HZR4C8P5]][[ADD207]]</p>{{state}}<p>化学シナプスの接続図だけでは、電気シナプス、受容体、神経修飾、細胞内・グリア関連の作用をすべて読み出せるとは限りません。どの要素を省略できるかは、対象機能と検証結果によって判断する必要があります。[[ADD187]][[XKB4CG64]]</p>''',
 '''<p>A conceptual model is <code>x(t+Δt)=F(x(t),u(t);θ)</code>. Here <code>x</code> includes voltages and adaptation states, <code>u</code> denotes sensory input, and <code>θ</code> includes connectivity and transmission parameters. Learning can change <code>θ</code> itself. Separating wiring from dynamics makes missing measurements explicit.[[HZR4C8P5]][[ADD207]]</p>{{state}}<p>A chemical-synapse map does not automatically specify electrical coupling, receptors, neuromodulation, or all intracellular and glial effects. Whether a detail can be omitted depends on the target function and validation evidence.[[ADD187]][[XKB4CG64]]</p>'''),
 s('measurement', '異なる計測を組み合わせる', 'Combine complementary measurements',
 '''<div class="tbl"><table><thead><tr><th>計測</th><th>得られる主な情報</th><th>単独では不足する点</th></tr></thead><tbody><tr><td>電子顕微鏡（EM）</td><td>微細形態とシナプス接続</td><td>固定後の像から生前の活動履歴を直接読めるわけではありません。</td></tr><tr><td>拡大顕微鏡・分子標識</td><td>形態と標識した分子の位置</td><td>標識の抜け、歪み、対応付け、撮像量を評価する必要があります。</td></tr><tr><td>電気生理・カルシウム画像</td><td>時間変化、刺激応答、集団活動</td><td>全細胞の全状態を同時に観測できるとは限りません。</td></tr><tr><td>摂動と行動計測</td><td>介入への応答と入出力関係</td><td>同じ行動を別の内部機構で実現できる可能性が残ります。</td></tr></tbody></table></div><p>MICrONSは構造と機能の対応付け、LICONNは光学的な密な再構成と分子情報の併用を考える具体例です。測定方式の比較では解像度だけでなく、体積、取得速度、欠損、費用、再構成誤差も必要です。[[6TNZ57MZ]][[ADD198]][[EVWH7H32]]</p>{{liconn}}''',
 '''<div class="tbl"><table><thead><tr><th>Measurement</th><th>Main information</th><th>What remains missing</th></tr></thead><tbody><tr><td>Electron microscopy (EM)</td><td>Ultrastructure and synaptic connectivity</td><td>Fixed images do not directly record the living brain's activity history.</td></tr><tr><td>Expansion microscopy and molecular labels</td><td>Morphology and locations of labelled molecules</td><td>Missing labels, deformation, registration, and imaging volume need evaluation.</td></tr><tr><td>Electrophysiology and calcium imaging</td><td>Temporal responses and population activity</td><td>These do not necessarily observe every state of every cell simultaneously.</td></tr><tr><td>Perturbation and behaviour</td><td>Intervention responses and input–output relationships</td><td>Different internal mechanisms can produce similar behaviour.</td></tr></tbody></table></div><p>MICrONS demonstrates structure–function registration; LICONN combines dense optical reconstruction with molecular information. A modality comparison needs volume, throughput, missing data, cost, and reconstruction error as well as resolution.[[6TNZ57MZ]][[ADD198]][[EVWH7H32]]</p>{{liconn}}'''),
 s('inverse', 'データからモデルへの逆問題', 'The inverse problem from data to model',
 '''<p>観測データに合うパラメーターが一つに決まるとは限りません。異なる細胞・シナプスの設定でも似た活動が生じることがあります。予測精度が高いモデルと、元の機構を同定できたモデルは、別の基準で評価してください。[[ADD190]][[274IXB72]]</p>{{inverse}}<p>接続情報、課題の制約、活動記録、介入実験を組み合わせると、候補を絞れます。ただし、学習に使った条件だけで評価すると、未知の刺激や損傷に対して誤ったモデルを見逃します。<a href="validation.html">検証設計</a>では、未使用の条件を先に確保します。[[XMYSQXY8]][[274IXB72]]</p>''',
 '''<p>Observed data may not identify a unique parameter set. Different cellular and synaptic configurations can generate similar activity. Predictive accuracy and recovery of the original mechanism therefore need separate evaluation.[[ADD190]][[274IXB72]]</p>{{inverse}}<p>Connectivity, task constraints, recordings, and interventions can narrow the possibilities. Evaluating only on fitted conditions can still miss incorrect responses to new stimuli or lesions. Reserve these conditions before fitting, as described in <a href="validation.html">validation design</a>.[[XMYSQXY8]][[274IXB72]]</p>'''),
 s('memory', '記憶を「保存できた」と言うための条件', 'What would demonstrate retained memory?',
 '''<p>記憶に関わるエングラム研究は、学習で変わる細胞集団とシナプスを調べています。しかし、記憶に関係する構造が見つかったことだけで、任意の個人の経験を読み出す手順が完成したとは言えません。必要な分子・構造状態についての研究者調査も、見解の分布を示すもので、抽出技術の実証ではありません。[[LP5F3H2Q]][[ADD210]]</p>{{memory}}<p>実験上は、学習前後の測定、同じ個体の想起課題、保持期間、未学習課題、介入後の変化を対応付けます。モデルに正解の行動だけを追加学習させた場合は、元の記憶を復元したことと区別して報告する必要があります。</p>''',
 '''<p>Engram research investigates ensembles and synapses altered by learning. Finding a memory-associated structure does not establish a procedure for reading arbitrary personal experiences. A survey about candidate molecular and structural substrates measures researchers' views, not the success of a memory-extraction technology.[[LP5F3H2Q]][[ADD210]]</p>{{memory}}<p>An experimental design should pair pre/post-learning measurements, recall in the same individual, retention intervals, untrained tasks, and intervention effects. Training a model on the desired answers must be distinguished from recovering the original memory.</p>'''),
 s('preservation', '保存は、復元までの連鎖の一段階です', 'Preservation is one stage in a longer chain',
 '''<p>アルデヒド安定化凍結保存（ASC）の研究は、保存後の神経微細構造を評価しています。固定した構造が観察できること、機能に必要な情報が残っていること、その情報をモデルへ読み出せることは、別々に検証する必要があります。[[SDSWEA5J]][[REPORTFINAL]]</p>{{preservation}}<p>WBE向けの研究課題は、保存前後で何が変わるかを測り、誤差をモデルの予測性能まで追跡することです。保存サービスの存在や美しい電子顕微鏡像を、そのまま復元成功の証拠にはできません。</p>''',
 '''<p>Aldehyde-stabilized cryopreservation (ASC) research evaluates preserved neural ultrastructure. Observable structure, retention of functionally necessary information, and successful readout into a model require separate tests.[[SDSWEA5J]][[REPORTFINAL]]</p>{{preservation}}<p>The WBE research question is what changes during preservation and how those errors affect model predictions. The availability of a preservation service or a well-preserved EM image is not evidence of successful reconstruction of function.</p>''')])

page('progress', '到達点を、実験の範囲で読む', 'Read progress at the scale of the experiment',
     '脳全体の構造、局所回路の機能、身体を含む行動。異なる成果を一つの完成率にまとめず、対象と検証内容を比較します。',
     'Whole-brain structure, local circuit function, and embodied behaviour are different achievements. Compare their scope and tests rather than assigning a single completion percentage.', [
 s('maps', '接続図の対象はどこまで広がりましたか', 'How far do the wiring maps extend?',
 '''<div class="tbl"><table><thead><tr><th>研究</th><th>対象と成果</th><th>読み取れないこと</th></tr></thead><tbody><tr><td>Cook et al., 2019</td><td><i>C. elegans</i>の雌雄同体と雄の全個体接続図。[[ADD192]]</td><td>全行動・全状態の再現。</td></tr><tr><td>Winding et al., 2023</td><td>幼生ハエ脳、3,016ニューロン。[[ADD209]]</td><td>成体や人の脳への単純な拡張。</td></tr><tr><td>FlyWire, 2024</td><td>雌成体ハエ脳、139,255ニューロン。[[ADD196]]</td><td>生前の学習履歴の読み出し。</td></tr><tr><td>MICrONS, 2025</td><td>マウス視覚野の部分体積で構造と活動を対応付け。[[6TNZ57MZ]]</td><td>マウス全脳の完全な機能再現。</td></tr><tr><td>BANC / MaleCNS, 2026</td><td>成体の脳と腹側神経索を統合する接続データ。独立したデータセットです。[[ADD199]][[ADD188]]</td><td>個体固有の全神経状態や記憶の再現。</td></tr></tbody></table></div>{{scopes}}<p>細胞数、ニューロン数、シナプス数、撮像体積を混同しないことが重要です。「全脳」「全中枢神経系」「局所体積」では範囲が異なります。また、再構成の誤接続や見落としは残り得るため、データの版と校正範囲も記録します。</p>''',
 '''<div class="tbl"><table><thead><tr><th>Study</th><th>Scope and result</th><th>What it does not establish</th></tr></thead><tbody><tr><td>Cook et al., 2019</td><td>Whole-animal connectomes of both <i>C. elegans</i> sexes.[[ADD192]]</td><td>Reproduction of all behaviours and states.</td></tr><tr><td>Winding et al., 2023</td><td>Larval fly brain, 3,016 neurons.[[ADD209]]</td><td>A direct scaling rule to adults or humans.</td></tr><tr><td>FlyWire, 2024</td><td>Adult female fly brain, 139,255 neurons.[[ADD196]]</td><td>Readout of the animal's learning history.</td></tr><tr><td>MICrONS, 2025</td><td>Paired structure and activity in a mouse visual-cortex volume.[[6TNZ57MZ]]</td><td>Complete functional emulation of a mouse brain.</td></tr><tr><td>BANC / MaleCNS, 2026</td><td>Separate datasets integrating adult brain and ventral nerve cord.[[ADD199]][[ADD188]]</td><td>Reproduction of all individual-specific neural states and memories.</td></tr></tbody></table></div>{{scopes}}<p>Cell counts, neuron counts, synapse counts, and imaging volumes are different quantities. A whole brain, a whole central nervous system, and a local volume have different boundaries. Reconstruction errors also remain possible; record the dataset version and proofreading scope.</p>'''),
 s('models', '接続図から機能を予測する', 'Predicting function from connectivity',
 '''<p><strong>Shiuら（2024）</strong>はハエ脳の接続情報に基づく計算モデルで感覚運動回路を調べ、実験と照合した予測を報告しました。<strong>Lappalainenら（2024）</strong>は視覚系の接続と運動検出課題を制約としてパラメーターを最適化し、26研究の神経活動測定と比較しました。後者は「接続だけから全機能が決まった」のではなく、課題の情報も使う方法です。[[V4GV7JAJ]][[XMYSQXY8]]</p><p>マウス視覚野の基盤モデルは、新しい個体や刺激領域への一般化を評価しました。応答予測の有力な基盤ですが、全脳の機構や個人の記憶の復元を意味しません。[[ADD197]]</p>{{fidelity}}''',
 '''<p><strong>Shiu et al. (2024)</strong> used a connectome-based fly brain model to investigate sensorimotor circuits and reported experimentally checked predictions. <strong>Lappalainen et al. (2024)</strong> optimized parameters under visual-connectivity and motion-detection task constraints, comparing predictions with neural measurements across 26 studies. The latter uses a task objective as well as connectivity.[[V4GV7JAJ]][[XMYSQXY8]]</p><p>A mouse visual-cortex foundation model tested generalization to new animals and stimulus domains. This advances response prediction without establishing recovery of whole-brain mechanisms or individual memories.[[ADD197]]</p>{{fidelity}}'''),
 s('embodiment', '身体をつないだモデルの読み方', 'Interpreting embodied models',
 '''<p>BAAIWormは、<i>C. elegans</i>の神経系、身体、環境を閉ループで結び、移動行動を再現する研究です。感覚から行動、再び感覚へという循環を評価する重要な方向です。[[ADD203]]</p><p>Eon Systemsが2026年に公開したハエのデモは、既存の脳モデル・視覚モデル・身体モデルを統合しています。同社の技術説明には、下行ニューロンから運動への対応を人が選んだ点、模倣学習による制御、内部ダイナミクスの検証不足が記載されています。Carboncopiesも「アップロード」と呼ぶための検証不足を指摘しています。ここでは<strong>身体を含むモデル統合</strong>として位置付け、個体の記憶や全内部状態の復元とは区別します。[[EON]][[CCFLY]]</p>''',
 '''<p>BAAIWorm closes the loop between a <i>C. elegans</i> nervous-system model, body, and environment to reproduce locomotion. This tests the sensory–motor–sensory cycle, an important direction for emulation research.[[ADD203]]</p><p>Eon Systems' 2026 fly demonstration integrates existing brain, vision, and body models. Its technical description identifies manually selected descending-neuron mappings, imitation-learned controllers, and missing validation of internal dynamics. Carboncopies also questions whether the evidence warrants the term “upload.” This guide treats the result as <strong>embodied model integration</strong>, distinct from recovery of an individual's memories and complete internal state.[[EON]][[CCFLY]]</p>'''),
 s('interfaces', '神経インターフェースが示すこと', 'What neural interfaces demonstrate',
 '''<p>発話や運動を支援する神経プロテーゼは、限られた神経信号から有用な機能を取り出す実例です。発話デコーディング、連続的な音声生成、脳と脊髄をつなぐインターフェースは、それぞれ異なる課題と対象者で評価されています。全脳の読み出しと同一視せず、閉ループ評価、長期安定性、個人適応の技術として参照します。[[ADD195]][[ADD202]][[ADD194]]</p><p>海馬プロテーゼによる記憶課題の支援も、限定された機能のモデル化と介入に関わる研究です。任意の記憶を別の人や機械へ移せたという結果ではありません。[[JHS9IFXX]]</p>''',
 '''<p>Speech and motor neuroprostheses show how useful function can be decoded from limited neural signals. Speech decoding, continuous voice generation, and brain–spine interfaces were evaluated in different tasks and participants. Their relevance includes closed-loop testing, long-term stability, and individual adaptation rather than whole-brain readout.[[ADD195]][[ADD202]][[ADD194]]</p><p>Hippocampal prostheses also investigate modelling and intervention for bounded memory tasks. These results do not demonstrate transfer of arbitrary memories to another person or machine.[[JHS9IFXX]]</p>'''),
 s('latest', '2026年の情報を読む際の注意点', 'Reading the 2026 record',
 '''<p>BANCの査読論文、MaleCNSの論文と公開データ、2026年秋の幼生ハエ中枢神経系の「first draft」を同じ確定度で扱わないでください。最後の資料はプレプリントです。プレプリント公開日、正式出版日、データ更新日はそれぞれ分けて記録します。[[ADD199]][[ADD188]][[MALEDATA]][[FLYLARVA2026]]</p><p>本サイトの到達点は2026年11月4日の確認に基づきます。新しい大規模データは重要ですが、機能再現の検証を省略できる理由にはなりません。</p>''',
 '''<p>The peer-reviewed BANC paper, the MaleCNS paper and public data, and the autumn 2026 larval CNS “first draft” have different publication statuses. The last item is a preprint. Track preprint release, journal publication, and dataset updates separately.[[ADD199]][[ADD188]][[MALEDATA]][[FLYLARVA2026]]</p><p>This account reflects sources checked on 4 November 2026. Larger datasets matter, but they do not remove the need for functional validation.</p>''')])

page('carboncopies', 'Carboncopies Foundationの研究', 'Carboncopies Foundation research',
     'WBEを測定・同定・検証の課題として進めるための、ロードマップ、開発基盤、ベンチマークを紹介します。',
     'A guide to the roadmap, development platform, and benchmarks for treating WBE as a measurement, identification, and validation problem.', [
 s('mission', '現在の研究の柱', 'Current research pillars',
 '''<p>Carboncopies Foundationは、媒体に依存しない心の実現を長期的な目標に掲げ、WBEに必要な研究を支援しています。公式研究ページでは、測定データを実行可能なモデルへ変換する方法と、その結果の検証を重視しています。本ページは同団体の公式サイトではなく、公開情報に基づく独立した解説です。[[CCFAQ]][[CCRESEARCH]]</p>{{carboncopies}}<div class="cards"><article class="card"><h3>Brain Emulation Challenge</h3><p>正解が既知の回路から仮想計測データを作り、復元方法を比較します。</p></article><article class="card"><h3>BrainGenix</h3><p>モデル構築・実行・実験を扱う開発基盤です。製品としての完成や生物のアップロード達成を意味しません。</p></article><article class="card"><h3>WBE Roadmap</h3><p>2008年のロードマップを起点に、技術の更新と必要な研究を継続的に整理しています。</p></article></div>''',
 '''<p>Carboncopies Foundation supports research toward substrate-independent minds, with WBE as a technical pathway. Its research page emphasizes converting measurements into executable models and validating the results. This page is an independent account of public information, not an official Foundation page.[[CCFAQ]][[CCRESEARCH]]</p>{{carboncopies}}<div class="cards"><article class="card"><h3>Brain Emulation Challenge</h3><p>Generate virtual measurements from known circuits and compare reconstruction methods.</p></article><article class="card"><h3>BrainGenix</h3><p>A development platform for models, execution, and experiments; its existence does not establish a finished upload system.</p></article><article class="card"><h3>WBE Roadmap</h3><p>An ongoing update of technical requirements and research needs, building on the 2008 roadmap.</p></article></div>'''),
 s('challenge', 'Brain Emulation Challengeの意味', 'What the Brain Emulation Challenge tests',
 '''<p>生物の脳では「本当のパラメーター」をすべて知ることができません。人工的に作った回路なら、正解を保管したまま観測だけを参加者に渡せます。仮想的な構造・活動の計測からモデルを復元し、構造、ダイナミクス、行動・入出力の複数の尺度で比較する設計です。[[CCCHALLENGE]]</p><ol class="plain"><li>正解の回路と課題を固定し、評価データを分離します。</li><li>観測の解像度、ノイズ、欠損、取得費用を変えます。</li><li>複数の復元手法を同じ情報条件で比較します。</li><li>人工回路で有効だった仮定を、生物のデータで別途検証します。</li></ol><p>上の手順は公式構想を踏まえた本サイトの実験設計案です。人工回路での成功は、実際の脳に必要な状態変数がすべて選べたことを保証しません。</p>''',
 '''<p>We cannot know every true parameter of a biological brain. A synthetic circuit allows ground truth to be retained while participants receive only observations. The Challenge reconstructs models from virtual structural and activity measurements and compares structure, dynamics, and behavioural or input–output performance.[[CCCHALLENGE]]</p><ol class="plain"><li>Fix the ground-truth circuit and task, reserving evaluation data.</li><li>Vary resolution, noise, missingness, and measurement cost.</li><li>Compare reconstruction methods under matched information budgets.</li><li>Test assumptions that worked in synthetic circuits against biological data.</li></ol><p>These steps are this guide's experimental design proposal informed by the official concept. Success on synthetic ground truth does not guarantee that every necessary biological state variable was represented.</p>'''),
 s('roadmap', 'ロードマップの公表状況', 'Roadmap publication status',
 '''<p>公式のロードマップページでは、忠実度と顕微鏡技術の論文が掲載され、逆問題や概念実証システムの項目は今後の公開項目として案内されています。ロードマップ全体が完成・検証済みになったと扱わないことが重要です。[[CCROADMAP]]</p><div class="tbl"><table><thead><tr><th>資料</th><th>技術的な要点</th><th>位置付け</th></tr></thead><tbody><tr><td>Linssen &amp; Koene, 2025</td><td>複雑な忠実度のトレードオフを、機能テストに結び付けて考えます。</td><td>公表済み論文。本サイトでは技術部分を扱います。[[XKB4CG64]]</td></tr><tr><td>Collins, Huffman &amp; Koene, 2025</td><td>哺乳類全脳コネクトミクスに向けて撮像方式を比較します。</td><td>査読論文。推定値は条件に依存します。[[EVWH7H32]]</td></tr><tr><td>Inverse Problem / Proof of Concept Systems</td><td>同定と実証系の課題です。</td><td>公式ページ上の今後の項目。[[CCROADMAP]]</td></tr></tbody></table></div>''',
 '''<p>The official roadmap lists published work on fidelity and microscopy, while the inverse-problem and proof-of-concept-system sections are presented as upcoming. The roadmap should not be treated as a completed and validated specification.[[CCROADMAP]]</p><div class="tbl"><table><thead><tr><th>Resource</th><th>Technical contribution</th><th>Status</th></tr></thead><tbody><tr><td>Linssen &amp; Koene, 2025</td><td>Relates complex fidelity tradeoffs to functional tests.</td><td>Published article; this guide covers its technical content.[[XKB4CG64]]</td></tr><tr><td>Collins, Huffman &amp; Koene, 2025</td><td>Compares imaging prospects for mammalian whole-brain connectomics.</td><td>Peer-reviewed paper; estimates depend on assumptions.[[EVWH7H32]]</td></tr><tr><td>Inverse Problem / Proof of Concept Systems</td><td>Identification and demonstrator requirements.</td><td>Upcoming sections on the official page.[[CCROADMAP]]</td></tr></tbody></table></div>'''),
 s('participate', '公式資料から研究に参加する', 'Use the official research resources',
 '''<p><a href="https://carboncopies.org/Research/BrainGenix/About/">BrainGenix</a>、<a href="https://carboncopies.org/Research/BrainGenix/Challenge/Overview/">Challenge概要</a>、<a href="https://carboncopies.org/Research/Roadmap/About/">Roadmap</a>を起点に、現在公開されている実験・ソフトウェアの条件を確認してください。利用できる機能や実行環境は更新され得ます。[[CCBRAINGENIX]][[CCCHALLENGE]]</p><p>公開Zoteroライブラリーは、直接WBEを扱う論文に加え、システム同定、神経プロテーゼ、記憶、計測技術をたどる入口になります。本サイトの文献探索もこの一覧を起点の一つにしています。収録されていること自体は、各論文の結論やアップロードの実現可能性を保証しません。[[CCLIBRARY]]</p>''',
 '''<p>Start with <a href="https://carboncopies.org/Research/BrainGenix/About/">BrainGenix</a>, the <a href="https://carboncopies.org/Research/BrainGenix/Challenge/Overview/">Challenge overview</a>, and the <a href="https://carboncopies.org/Research/Roadmap/About/">roadmap</a>. Check the currently released experiments and software requirements; capabilities and execution environments can change.[[CCBRAINGENIX]][[CCCHALLENGE]]</p><p>The public Zotero library links direct WBE work with system identification, neural prosthetics, memory, and measurement research. It was one starting point for this guide's literature search. Inclusion in the library does not itself validate a paper's conclusions or the feasibility of uploading.[[CCLIBRARY]]</p>''')])

page('validation', '「再現できた」を検証する', 'Testing whether an emulation is correct',
     '成功条件を先に決め、学習に使わなかった条件と介入で評価します。見た目の似た行動だけでは、内部の対応は決まりません。',
     'Define success first, then evaluate on held-out conditions and interventions. Similar-looking behaviour alone does not identify the internal mechanism.', [
 s('levels', '一つの得点で済ませない', 'Use more than one score',
 '''<div class="tbl"><table><thead><tr><th>検証対象</th><th>具体的な問い</th><th>評価の例</th></tr></thead><tbody><tr><td>構造</td><td>細胞・接続・型が対応していますか。</td><td>見落とし、誤結合、型の混同行列、校正範囲。</td></tr><tr><td>ダイナミクス</td><td>未使用刺激への活動が一致しますか。</td><td>時系列予測、潜在状態、安定性、時間尺度。</td></tr><tr><td>因果応答</td><td>同じ介入で同じ変化が起こりますか。</td><td>刺激・抑制・切断への応答と回復。</td></tr><tr><td>学習と記憶</td><td>その個体の獲得した能力が保持されますか。</td><td>保持、再学習、忘却、未学習条件との比較。</td></tr><tr><td>身体と環境</td><td>閉ループでも対応が保たれますか。</td><td>新しい環境、感覚遅延、身体条件の変更。</td></tr></tbody></table></div><p>これは本サイトが提案する検証整理であり、合意された認証規格ではありません。機能テストを中心に忠実度を定義する考え方と、システム同定の限界に関する研究を踏まえています。[[XKB4CG64]][[274IXB72]]</p>{{validation}}''',
 '''<div class="tbl"><table><thead><tr><th>Target</th><th>Question</th><th>Example evaluation</th></tr></thead><tbody><tr><td>Structure</td><td>Do cells, connections, and types correspond?</td><td>Misses, false merges, type confusion, proofreading coverage.</td></tr><tr><td>Dynamics</td><td>Do responses match on held-out inputs?</td><td>Time-series prediction, latent state, stability, timescales.</td></tr><tr><td>Causal response</td><td>Does the same intervention cause the same change?</td><td>Stimulation, suppression, lesions, recovery.</td></tr><tr><td>Learning and memory</td><td>Are the individual's acquired abilities retained?</td><td>Retention, relearning, forgetting, untrained controls.</td></tr><tr><td>Body and environment</td><td>Does correspondence survive closed-loop interaction?</td><td>Novel environments, sensory delays, changed body conditions.</td></tr></tbody></table></div><p>This is the guide's proposed evaluation framework, not a consensus certification standard. It draws on functional fidelity and limitations of system identification.[[XKB4CG64]][[274IXB72]]</p>{{validation}}'''),
 s('benchmarks', '実際に使える検証の入口', 'Practical validation starting points',
 '''<p><strong>ZAPBench</strong>は、幼生ゼブラフィッシュの7万超のニューロンの活動記録を基に、全脳規模の活動予測を比較するベンチマークです。観測条件での活動予測を評価するもので、構造の完全回復や記憶の転送を直接認定するものではありません。[[FHPYMIG8]]</p><p><strong>Brain Emulation Challenge</strong>は、人工回路の正解を用いて、観測条件と復元手法の関係を調べます。<strong>MICrONS</strong>は生物学的な構造と機能の対応を調べるデータ基盤になります。三者は目的が異なり、相互に置き換えられません。[[CCCHALLENGE]][[6TNZ57MZ]]</p>''',
 '''<p><strong>ZAPBench</strong> benchmarks brain-wide activity prediction using recordings of over 70,000 neurons in a larval zebrafish. It measures activity prediction under recorded conditions, not complete structural recovery or memory transfer.[[FHPYMIG8]]</p><p>The <strong>Brain Emulation Challenge</strong> uses synthetic ground truth to examine measurement and reconstruction choices. <strong>MICrONS</strong> supports biological structure–function comparisons. These resources address different questions and are complementary rather than interchangeable.[[CCCHALLENGE]][[6TNZ57MZ]]</p>'''),
 s('protocol', '比較を成立させる実験手順', 'A protocol for interpretable comparison',
 '''<ol class="plain"><li><strong>対象を固定：</strong>個体、領域、課題、時間尺度、保持すべき機能を記述します。</li><li><strong>データを分離：</strong>時系列の近接区間が学習と評価に漏れないようにし、刺激・セッション・個体のどれを未知にするか決めます。</li><li><strong>基準を用意：</strong>単純モデル、接続をシャッフルしたモデル、機能データだけのモデルを同じ条件で比較します。</li><li><strong>介入を予約：</strong>評価用の刺激・抑制・切断条件を最適化から除外します。</li><li><strong>不確実性を報告：</strong>試行数、個体差、測定誤差、乱数の差、信頼区間を結果と一緒に示します。</li><li><strong>失敗を残す：</strong>動かなかった条件、追加学習の有無、計算費用とデータの版を公開します。</li></ol><p>これは再現研究の設計案です。特定の評価値を超えれば「アップロード成功」となる閾値を与えるものではありません。</p>''',
 '''<ol class="plain"><li><strong>Fix the target:</strong> specify individual, region, task, timescale, and functions to retain.</li><li><strong>Separate data:</strong> prevent leakage across neighbouring time windows; state whether stimulus, session, or animal is held out.</li><li><strong>Provide baselines:</strong> compare simple models, shuffled connectivity, and activity-only models under matched conditions.</li><li><strong>Reserve interventions:</strong> keep evaluation stimulation, suppression, and lesion conditions out of optimization.</li><li><strong>Report uncertainty:</strong> include trial counts, animal variation, measurement error, random seeds, and confidence intervals.</li><li><strong>Preserve failures:</strong> publish failing conditions, extra training, computational cost, and data versions.</li></ol><p>This is a reproducibility-oriented design proposal. It does not supply a score threshold that certifies “successful uploading.”</p>'''),
 s('negative', '失敗も実現への情報になります', 'Failures also move the research forward',
 '''<p>接続図だけのモデルが特定の介入で失敗した場合、その失敗は追加すべき情報を絞る手掛かりになります。受容体、伝達確率、適応、神経修飾などを一度に全部追加せず、一つずつ追加して改善量を測ります。必要な計測の優先順位を決めることが、WBEの実現に向けた具体的な成果になります。</p>''',
 '''<p>If a connectivity-only model fails on a particular intervention, the failure can identify missing information. Add receptor properties, release probability, adaptation, or neuromodulation in controlled steps, measuring the improvement each brings. Establishing which measurements are necessary is a concrete contribution toward WBE.</p>''')])

page('future', '実現年より、解くべき依存関係を', 'A roadmap of dependencies, not a promised date',
     '計測、再構成、同定、計算、検証のどこで誤差と費用が増えるのかを明らかにします。',
     'Identify where errors and costs grow across measurement, reconstruction, identification, computation, and validation.', [
 s('gates', '次の段階へ進むための条件', 'Evidence needed to advance',
 '''{{roadmap}}<div class="tbl"><table><thead><tr><th>段階</th><th>必要な成果物</th><th>次へ進む条件の例</th></tr></thead><tbody><tr><td>測定</td><td>対応付けられた構造・活動・分子データ</td><td>欠損と歪みを定量化できること。</td></tr><tr><td>再構成</td><td>校正履歴を持つ細胞・接続モデル</td><td>構造誤差が下流の結果へ与える影響を測れること。</td></tr><tr><td>同定</td><td>候補モデルと不確実性</td><td>未使用の刺激・介入で基準モデルを上回ること。</td></tr><tr><td>実行</td><td>再現可能なモデルと計算費用</td><td>必要な時間尺度で安定して動くこと。</td></tr><tr><td>検証</td><td>同じ個体の独立したテスト</td><td>保持すべき機能を事前の基準で評価できること。</td></tr></tbody></table></div><p>この段階整理は編集上の研究提案です。2008年のロードマップ、2025年の技術レビュー、現在のCarboncopiesの更新作業を参考にしています。[[9B7EMU3K]][[REPORTFINAL]][[CCROADMAP]]</p>''',
 '''{{roadmap}}<div class="tbl"><table><thead><tr><th>Stage</th><th>Required output</th><th>Example advancement criterion</th></tr></thead><tbody><tr><td>Measurement</td><td>Registered structure, activity, and molecular data</td><td>Quantify missingness and distortion.</td></tr><tr><td>Reconstruction</td><td>Cells and connections with proofreading provenance</td><td>Measure how structural errors affect downstream results.</td></tr><tr><td>Identification</td><td>Candidate models and uncertainty</td><td>Beat baselines on held-out inputs and interventions.</td></tr><tr><td>Execution</td><td>Reproducible model and computational cost</td><td>Run stably at the required timescale.</td></tr><tr><td>Validation</td><td>Independent tests in the same individual</td><td>Evaluate retained functions against prespecified criteria.</td></tr></tbody></table></div><p>This staged plan is an editorial research proposal informed by the 2008 roadmap, the 2025 review, and current Carboncopies updates.[[9B7EMU3K]][[REPORTFINAL]][[CCROADMAP]]</p>'''),
 s('scaling', '撮像と計算の量を試算する', 'Explore imaging and computation scale',
 '''<p>大規模化では、解像度を上げたときのデータ量、シナプス状態の保存量、更新頻度が効いてきます。下の計算機は単純な量の関係だけを示します。圧縮、索引、通信、冗長保存、区画モデル、前処理、校正、学習の費用は含みません。実際の費用見積もりには方式ごとの実測値が必要です。[[EVWH7H32]]</p>{{calculator}}''',
 '''<p>Scaling depends on imaging resolution, synaptic state storage, and update frequency. This calculator shows simple quantity relationships only. It excludes compression, indexing, communication, replication, compartments, preprocessing, proofreading, and training. Real cost estimates need measured performance for the chosen method.[[EVWH7H32]]</p>{{calculator}}'''),
 s('bottlenecks', '計算機が速くなっても残る問題', 'What faster computers do not solve',
 '''<p>計算資源は必要条件の一つですが、必要な状態を測れていなければ、速い計算機でもその情報は復元できません。画像の分割、細胞の対応付け、パラメーターの識別可能性、学習則、検証用データが連続した課題になります。[[EVWH7H32]][[XKB4CG64]][[274IXB72]]</p><p>単一の実現年を示すより、どの実証がいつ可能になったかを更新する方が研究を進めやすくなります。特に、人への外挿では、種、領域、学習履歴、記録できる時間尺度の違いを明示してください。</p>''',
 '''<p>Compute is one requirement. Faster hardware cannot recover unmeasured information simply by running longer. Segmentation, registration, parameter identifiability, learning rules, and independent evaluation data remain linked challenges.[[EVWH7H32]][[XKB4CG64]][[274IXB72]]</p><p>Tracking demonstrated capabilities is more useful for research planning than assigning one arrival date. Extrapolation to humans must state differences in species, region, learning history, and observable timescales.</p>''')])

page('action', 'いま着手できる研究', 'Research you can start now',
     '公開データと再現可能な評価から、必要な情報と不足している情報を一つずつ絞ります。',
     'Use public data and reproducible tests to determine which information is necessary and what remains missing.', [
 s('projects', '四つの具体的な課題', 'Four concrete projects',
 '''<div class="cards"><article class="card"><span class="k">同定</span><h3>どの観測が必要でしょうか</h3><p>人工回路の観測数とノイズを変え、復元モデルの未使用介入への応答を比較します。出力は「必要な観測量と誤差」の関係です。[[CCCHALLENGE]]</p></article><article class="card"><span class="k">再構成</span><h3>接続誤差は何を壊しますか</h3><p>公開接続図に制御した欠損・誤結合を加え、予測への影響を調べます。真のデータの誤りと、実験用に加えた誤りを分けます。[[ADD196]]</p></article><article class="card"><span class="k">活動予測</span><h3>未知の条件に一般化しますか</h3><p>ZAPBenchなどで既存モデルと単純基準を再現し、時間・刺激・セッションの分割を変えて頑健性を調べます。[[FHPYMIG8]]</p></article><article class="card"><span class="k">機構</span><h3>接続の情報はどれだけ効きますか</h3><p>活動だけのモデル、真の接続を使うモデル、接続をシャッフルしたモデルを比較します。課題と計算予算をそろえます。[[XMYSQXY8]]</p></article></div><p>これらは本サイトの研究提案であり、実施済みの結果ではありません。</p>''',
 '''<div class="cards"><article class="card"><span class="k">Identification</span><h3>Which observations are necessary?</h3><p>Vary observation count and noise in synthetic circuits; compare responses to held-out interventions. Report the relationship between measurement budget and error.[[CCCHALLENGE]]</p></article><article class="card"><span class="k">Reconstruction</span><h3>What do wiring errors break?</h3><p>Add controlled missing and false connections to a public connectome and measure predictive changes. Distinguish injected errors from known dataset errors.[[ADD196]]</p></article><article class="card"><span class="k">Prediction</span><h3>Does it generalize?</h3><p>Reproduce models and simple baselines on resources such as ZAPBench. Test robustness to time, stimulus, and session splits.[[FHPYMIG8]]</p></article><article class="card"><span class="k">Mechanism</span><h3>How much does connectivity help?</h3><p>Compare activity-only, true-connectivity, and shuffled-connectivity models with matched tasks and computational budgets.[[XMYSQXY8]]</p></article></div><p>These are proposed projects, not results already obtained by this site.</p>'''),
 s('workflow', '成果物を先に決める', 'Specify the deliverable first',
 '''<ol class="plain"><li>論文を一つ選び、データの版、利用条件、再現する図・表を固定します。</li><li>最小の基準モデルで処理を通し、分割と評価値を確認します。</li><li>一つの仮説だけを変更し、独立した評価条件で比較します。</li><li>設定、実行環境、所要時間、乱数、成功・失敗を保存します。</li><li>説明可能な差と未解決の差を分けて公開します。</li></ol><p>NEURONやBrain Modeling ToolKitのような基盤はモデル実装を助けますが、ソフトウェアを使ったこと自体は生物学的な妥当性の証明になりません。[[Q8SGY2SV]][[9DXWPDVH]]</p>''',
 '''<ol class="plain"><li>Select a paper and freeze the data version, usage conditions, and target figure or table.</li><li>Run a minimal baseline and check the data split and metric.</li><li>Change one hypothesis and compare on independent evaluation conditions.</li><li>Save configuration, environment, runtime, seeds, successes, and failures.</li><li>Publish explainable differences separately from unresolved discrepancies.</li></ol><p>Platforms such as NEURON and the Brain Modeling ToolKit help implement models. Using a simulator does not itself establish biological validity.[[Q8SGY2SV]][[9DXWPDVH]]</p>'''),
 s('skills', '専門ごとの参加口', 'Where different skills contribute',
 '''<p><strong>実験神経科学：</strong>構造と活動の対応、介入、長期記録。<strong>顕微鏡・画像処理：</strong>取得速度、変形補正、分割と校正。<strong>数理・機械学習：</strong>逆問題、識別可能性、不確実性、一般化。<strong>計算基盤：</strong>メモリー、分散実行、再現性。<strong>資料整理：</strong>DOI、版、訂正、データとコードの対応を保つことです。</p><p>「脳を丸ごと動かす」という目標を、検証可能な小さな成果物につなげることが、実現に向けた作業になります。</p>''',
 '''<p><strong>Experimental neuroscience:</strong> structure–activity registration, interventions, longitudinal recordings. <strong>Microscopy and image analysis:</strong> throughput, deformation correction, segmentation, proofreading. <strong>Mathematics and machine learning:</strong> inverse problems, identifiability, uncertainty, generalization. <strong>Computing:</strong> memory, distributed execution, reproducibility. <strong>Literature curation:</strong> maintain links among DOI, version, corrections, data, and code.</p><p>Turn the ambition of running a brain into small, falsifiable deliverables that resolve a necessary part of the problem.</p>''')])

page('history', '構想から、測定と検証の研究へ', 'From a proposal to measurement and validation',
     '歴史的な見通しと、実際に成立した技術を区別してたどります。',
     'Trace the difference between historical expectations and experimentally established capabilities.', [
 s('early', '古い構想を、現在の証拠と混ぜない', 'Keep historical proposals in their context',
 '''<p>Joseph StroutのMind Uploading Home Pageは、走査、計算機、置換などの技術的構想を整理した初期ウェブ資料です。ページは2006年の更新日を示しています。研究課題の歴史を知る資料として有用ですが、現在の解像度、費用、計算性能、達成状況の根拠にはそのまま使えません。[[STROUT]]</p><p>SandbergとBostromの2008年の技術ロードマップは、保存から走査、解釈、シミュレーションまでを依存関係として整理しました。その枠組みは参照点になりますが、当時の数値見積もりは現在の実測や方式に照らして更新する必要があります。[[9B7EMU3K]]</p>''',
 '''<p>Joseph Strout's Mind Uploading Home Page is an early web resource organizing scanning, computation, and replacement proposals. It displays a 2006 update date. It is useful historical context, but its resolution, cost, computing, and feasibility assumptions are not current evidence.[[STROUT]]</p><p>Sandberg and Bostrom's 2008 technical roadmap organized preservation, scanning, interpretation, and simulation as dependencies. Its framework remains a reference point; quantitative estimates need reassessment against current measurements and methods.[[9B7EMU3K]]</p>'''),
 s('timeline', '技術の積み重ね', 'A sequence of technical advances',
 '''<ol class="beats"><li class="beat"><span class="beat-date">1952</span><h3>電気的な動作を数式で記述</h3><p>Hodgkin–Huxleyモデルは膜電流を定量的に扱う基盤です。細胞の動作モデルと、個体全体の再現の距離を考える出発点になります。[[ADD207]]</p></li><li class="beat"><span class="beat-date">2008–2019</span><h3>ロードマップと小さな神経系</h3><p>WBEの技術工程が整理され、全個体接続図や統合モデルの研究基盤が広がりました。[[9B7EMU3K]][[ADD192]][[8ZGBRSYV]]</p></li><li class="beat"><span class="beat-date">2023–2024</span><h3>ハエの脳規模へ</h3><p>幼生脳、成体脳の接続図と、接続に制約された機能予測が前進しました。[[ADD209]][[ADD196]][[XMYSQXY8]]</p></li><li class="beat"><span class="beat-date">2025</span><h3>対応を測り、比較する</h3><p>MICrONS、LICONN、ZAPBench、忠実度の研究が、測定と検証の具体的な課題を広げました。[[6TNZ57MZ]][[ADD198]][[FHPYMIG8]][[XKB4CG64]]</p></li><li class="beat"><span class="beat-date">2026</span><h3>脳と身体を結び付ける</h3><p>脳と腹側神経索の統合データ、身体を含むモデル、機能検証の議論が進んでいます。これらを人のアップロード達成と解釈する段階ではありません。[[ADD199]][[ADD188]][[EON]][[CCFLY]]</p></li></ol>''',
 '''<ol class="beats"><li class="beat"><span class="beat-date">1952</span><h3>Quantifying electrical dynamics</h3><p>The Hodgkin–Huxley model provides a foundation for membrane-current modelling. It also illustrates the distance between modelling a cellular process and reproducing an individual organism.[[ADD207]]</p></li><li class="beat"><span class="beat-date">2008–2019</span><h3>Roadmaps and small nervous systems</h3><p>WBE requirements were organized, while whole-animal connectomes and integrated-model research expanded.[[9B7EMU3K]][[ADD192]][[8ZGBRSYV]]</p></li><li class="beat"><span class="beat-date">2023–2024</span><h3>Reaching fly-brain scale</h3><p>Larval and adult brain connectomes advanced alongside connectome-constrained functional prediction.[[ADD209]][[ADD196]][[XMYSQXY8]]</p></li><li class="beat"><span class="beat-date">2025</span><h3>Measuring and benchmarking correspondence</h3><p>MICrONS, LICONN, ZAPBench, and fidelity research sharpened measurement and validation questions.[[6TNZ57MZ]][[ADD198]][[FHPYMIG8]][[XKB4CG64]]</p></li><li class="beat"><span class="beat-date">2026</span><h3>Linking brains with bodies</h3><p>Brain-and-cord datasets, embodied models, and functional-validation debates progressed. They do not establish human uploading.[[ADD199]][[ADD188]][[EON]][[CCFLY]]</p></li></ol>'''),
 s('review', 'レビューは、入口として使う', 'Use reviews as entry points',
 '''<p>State of Brain Emulation Report 2025は、関連技術を広く整理したレビューです。保存したarXiv v3は2025年11月5日版の178ページであり、2026年に公表された182ページの最終版とは区別します。重要な主張は引用先の個別研究までたどり、実験条件と制約を確認してください。[[REPORT2025]][[REPORTFINAL]]</p>''',
 '''<p>The State of Brain Emulation Report 2025 surveys enabling technologies. The archived arXiv v3 is the 178-page version dated 5 November 2025, distinct from the 182-page final report released in 2026. Follow consequential claims back to the underlying studies and check their experimental conditions.[[REPORT2025]][[REPORTFINAL]]</p>''')])

page('resources', '文献・データ・用語', 'Literature, data, and terminology',
     '直接WBEを扱う研究から、計測、記憶、逆問題、神経プロテーゼ、計算基盤までをたどれます。',
     'Explore direct WBE research and enabling work on measurement, memory, inverse problems, neural prosthetics, and computing.', [
 s('start', '最初に読む資料', 'Start here',
 '''<p><strong>全体像：</strong>2008年ロードマップとState of Brain Emulation Report。<strong>計測：</strong>Collinsらの方式比較とLICONN。<strong>同定：</strong>LappalainenらとHanらの検証研究。<strong>評価：</strong>LinssenとKoene、ZAPBench、Brain Emulation Challengeが入口になります。[[9B7EMU3K]][[REPORTFINAL]][[EVWH7H32]][[ADD198]][[XMYSQXY8]][[274IXB72]][[XKB4CG64]][[FHPYMIG8]][[CCCHALLENGE]]</p>''',
 '''<p><strong>Overview:</strong> the 2008 roadmap and State of Brain Emulation Report. <strong>Measurement:</strong> Collins et al.'s modality comparison and LICONN. <strong>Identification:</strong> Lappalainen et al. and Han et al. <strong>Evaluation:</strong> Linssen and Koene, ZAPBench, and the Brain Emulation Challenge.[[9B7EMU3K]][[REPORTFINAL]][[EVWH7H32]][[ADD198]][[XMYSQXY8]][[274IXB72]][[XKB4CG64]][[FHPYMIG8]][[CCCHALLENGE]]</p>'''),
 s('library', '検索できる文献カタログ', 'Searchable literature catalogue',
 '''<p>以下は探索用カタログです。各項目の掲載は、本文の精読、結論の追試、WBEの達成を意味しません。本文で根拠として使った文献は各ページ末尾にも番号付きで掲載しています。資料の種類と、本文を確認できた範囲を区別してください。</p>{{library}}''',
 '''<p>This is a discovery catalogue. Inclusion does not mean that every paper has been read in full, reproduced, or shown to achieve WBE. Sources supporting the guide appear in numbered references on each page. Distinguish publication type from the extent of full-text verification.</p>{{library}}'''),
 s('method', '探索範囲と引用の方法', 'Search scope and citation method',
 '''<p>Carboncopiesの公開Zotero一覧、同団体のFAQ・研究・ロードマップ、Stroutの歴史資料、既存サイトの文献を起点に、出版社、著者公開版、Crossref、Europe PMCで書誌と公開状況を照合しました。2024–2026年の接続図、構造と機能の対応、顕微鏡、活動予測、神経インターフェースを追加しました。哲学・倫理・フィクションを主題とする資料や、対象との関係が薄い資料は収録対象から外しています。[[CCLIBRARY]][[CCFAQ]][[STROUT]]</p><p>本文は番号式引用です。書誌には著者、題名、出版年、媒体、巻号・ページまたは論文番号（取得できた項目）、DOIまたは原文URLを記載します。著者が多い場合は先頭6名と「et al.」を表示し、JSON/BibTeXには取得した全著者を保持します。ウェブ資料は確認日を付け、プレプリントと査読論文を区別します。</p><p>完全網羅を保証するシステマティックレビューではありません。検索範囲、選択理由、取得できなかった資料を記録し、更新可能な文献集として扱います。公開サイトでは第三者の論文本文を再配布せず、正規の配布先へ案内します。</p>''',
 '''<p>The search began with Carboncopies' public Zotero collection, its FAQ, research and roadmap pages, Strout's historical resource, and the previous site's references. Bibliographic records and access were checked against publishers, author versions, Crossref, and Europe PMC. Additions emphasize 2024–2026 connectomes, structure–function studies, microscopy, activity prediction, and neural interfaces. Works primarily about philosophy, ethics, fiction, or weakly related topics were excluded.[[CCLIBRARY]][[CCFAQ]][[STROUT]]</p><p>The guide uses numbered citations. Records include authors, title, year, venue, available volume/issue/pages or article number, and DOI or source URL. Long author lists display the first six followed by “et al.”; JSON and BibTeX retain the retrieved author lists. Web resources include an access date, and preprints are distinguished from peer-reviewed articles.</p><p>This is not an exhaustive systematic review. Scope, selection, and retrieval gaps are recorded for future updates. The public site links to legitimate distribution sources rather than redistributing third-party full texts.</p>'''),
 s('glossary', '用語を混同しないために', 'Terms that should remain distinct',
 '''<dl class="glossary"><dt>コネクトーム</dt><dd>指定した範囲の神経接続を表すデータです。接続図の粒度や化学・電気シナプスの範囲を確認します。</dd><dt>シミュレーション</dt><dd>仮定したモデルを計算して振る舞いを調べることです。</dd><dt>エミュレーション</dt><dd>対象となる系との機能的な対応を目指す再現です。何を一致させるかの定義と検証が必要です。</dd><dt>システム同定</dt><dd>観測した入力と出力などから、モデルの構造やパラメーターを推定することです。</dd><dt>識別可能性</dt><dd>利用できる観測によって、異なる候補モデルを区別できる性質です。</dd><dt>エングラム</dt><dd>記憶の保持や想起に関わる物理的変化・細胞集団を研究する概念です。任意の経験を読む完成済みの符号表ではありません。</dd><dt>デジタルツイン</dt><dd>使われ方が広い語です。対象個体、測定範囲、更新方法、検証課題を併記して意味を限定します。</dd></dl>''',
 '''<dl class="glossary"><dt>Connectome</dt><dd>A representation of neural connectivity within a specified boundary. Check resolution and the coverage of chemical and electrical synapses.</dd><dt>Simulation</dt><dd>Computing the behaviour of an assumed model.</dd><dt>Emulation</dt><dd>Reproduction aimed at functional correspondence to a target system, requiring an explicit definition and tests of correspondence.</dd><dt>System identification</dt><dd>Estimating model structure or parameters from observed inputs, outputs, and related measurements.</dd><dt>Identifiability</dt><dd>The ability to distinguish candidate models using the available observations.</dd><dt>Engram</dt><dd>A concept for studying physical changes and cell ensembles associated with memory retention and recall; not a complete codebook for arbitrary experiences.</dd><dt>Digital twin</dt><dd>A broad term that needs a specified individual, measurement scope, update rule, and validation task.</dd></dl>''')])
